            data.locoIconUrl = assetIconOrNull(resolveMbtaLocoIconUrl(payload.locoIconUrl || (data.locoType && MBTA_LOCO_TYPES[data.locoType]) || null, data.locoType));
            if (!payload.locoIconUrl && !data.locoType) data.locoIconUrl = null;
