          name: s.name || '',
          stopId: String(s.id || s.stopId || ''),
          scheduled: s.formattedScheduledTime || null,
          predicted: s.formattedPredictedTime || null,
          actual: actual,
          completed: !!s.isCompleted,
          delayMinutes: Number(s.delayMinutes) || 0
