          routeName: line.name,
          routeColor: line.color,
          lat: lat,
          lng: lng,
          destName: '',
          currentStopName: nextStop,
          direction: direction,
          statusText: delay.text,
          statusPillClass: delay.pill,
          delayMinutes: delay.minutes,
          lastModified: lastModified || '',
          lastModifiedMs: njtEasternMs(lastModified),
          schedDep: schedDep || '',
