          const parts = k.split('|');
          const agency = parts[0] || '';
          const id = parts.slice(1).join('|');
          const pretty = (typeof agencyPrettyName === 'function') ? agencyPrettyName(agency) : agency.toUpperCase();
          const name = u && u.name && u.name !== id ? (' · ' + u.name) : '';
          const label = pretty + ' ' + id + name;
